#include "stdlib/stats/base/dists/studentized-range/quantile.h"
#include "stdlib/stats/base/dists/studentized-range/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/pinf.h"
#include <math.h>

static const double PCUT = 1.0e-8;
static const int JMAX = 28;

/* apnorminv coefficients for P close to 0.5: */
static const double inv_a0 = 3.3871328727963666080E0;
static const double inv_a1 = 1.3314166789178437745E+2;
static const double inv_a2 = 1.9715909503065514427E+3;
static const double inv_a3 = 1.3731693765509461125E+4;
static const double inv_a4 = 4.5921953931549871457E+4;
static const double inv_a5 = 6.7265770927008700853E+4;
static const double inv_a6 = 3.3430575583588128105E+4;
static const double inv_a7 = 2.5090809287301226727E+3;
static const double inv_b1 = 4.2313330701600911252E+1;
static const double inv_b2 = 6.8718700749205790830E+2;
static const double inv_b3 = 5.3941960214247511077E+3;
static const double inv_b4 = 2.1213794301586595867E+4;
static const double inv_b5 = 3.9307895800092710610E+4;
static const double inv_b6 = 2.8729085735721942674E+4;
static const double inv_b7 = 5.2264952788528545610E+3;

/* apnorminv coefficients for P not close to 0, 0.5, or 1: */
static const double inv_c0 = 1.42343711074968357734E0;
static const double inv_c1 = 4.63033784615654529590E0;
static const double inv_c2 = 5.76949722146069140550E0;
static const double inv_c3 = 3.64784832476320460504E0;
static const double inv_c4 = 1.27045825245236838258E0;
static const double inv_c5 = 2.41780725177450611770E-1;
static const double inv_c6 = 2.27238449892691845833E-2;
static const double inv_c7 = 7.74545014278341407640E-4;
static const double inv_d1 = 2.05319162663775882187E0;
static const double inv_d2 = 1.67638483018380384940E0;
static const double inv_d3 = 6.89767334985100004550E-1;
static const double inv_d4 = 1.48103976427480074590E-1;
static const double inv_d5 = 1.51986665636164571966E-2;
static const double inv_d6 = 5.47593808499534494600E-4;
static const double inv_d7 = 1.05075007164441684324E-9;

/* apnorminv coefficients for P near 0 or 1: */
static const double inv_e0 = 6.65790464350110377720E0;
static const double inv_e1 = 5.46378491116411436990E0;
static const double inv_e2 = 1.78482653991729133580E0;
static const double inv_e3 = 2.96560571828504891230E-1;
static const double inv_e4 = 2.65321895265761230930E-2;
static const double inv_e5 = 1.24266094738807843860E-3;
static const double inv_e6 = 2.71155556874348757815E-5;
static const double inv_e7 = 2.01033439929228813265E-7;
static const double inv_f1 = 5.99832206555887937690E-1;
static const double inv_f2 = 1.36929880922735805310E-1;
static const double inv_f3 = 1.48753612908506148525E-2;
static const double inv_f4 = 7.86869131145613259100E-4;
static const double inv_f5 = 1.84631831751005468180E-5;
static const double inv_f6 = 1.42151175831644588870E-7;
static const double inv_f7 = 2.04426310338993978564E-15;

/**
* Returns the normal deviate Z corresponding to a given lower tail area of p.
*
* @private
* @param p    lower tail area
* @return     normal deviate
*/
static double apnorminv( const double p ) {
	double ppnd;
	double q;
	double r;

	q = p - 0.5;
	if ( fabs( q ) <= 0.425 ) {
		r = 0.180625 - ( q * q );
		ppnd = q * (((((((inv_a7 * r + inv_a6) * r + inv_a5) * r + inv_a4) * r + inv_a3) * r + inv_a2) * r + inv_a1) * r + inv_a0) / (((((((inv_b7 * r + inv_b6) * r + inv_b5) * r + inv_b4) * r + inv_b3) * r + inv_b2) * r + inv_b1) * r + 1.0);
	} else {
		if ( q < 0.0 ) {
			r = p;
		} else {
			r = 1.0 - p;
		}
		if ( r <= 0.0 ) {
			ppnd = 0.0;
		} else {
			r = sqrt( -log( r ) );
			if ( r <= 5.0 ) {
				r -= 1.6;
				ppnd = (((((((inv_c7 * r + inv_c6) * r + inv_c5) * r + inv_c4) * r + inv_c3) * r + inv_c2) * r + inv_c1) * r + inv_c0) / (((((((inv_d7 * r + inv_d6) * r + inv_d5) * r + inv_d4) * r + inv_d3) * r + inv_d2) * r + inv_d1) * r + 1.0);
			} else {
				r -= 5.0;
				ppnd = (((((((inv_e7 * r + inv_e6) * r + inv_e5) * r + inv_e4) * r + inv_e3) * r + inv_e2) * r + inv_e1) * r + inv_e0) / (((((((inv_f7 * r + inv_f6) * r + inv_f5) * r + inv_f4) * r + inv_f3) * r + inv_f2) * r + inv_f1) * r + 1.0);
			}
			if ( q < 0.0 ) {
				ppnd = -ppnd;
			}
		}
	}
	return ppnd;
}

/**
* Calculates an initial percentile from the studentized range distribution.
*
* @private
* @param p    probability
* @param v    degrees of freedom
* @param r    sample size for range
* @return     initial percentile
*/
static double qtrngo( const double p, const double v, const double r ) {
	double q;
	double t;

	t = apnorminv( 0.5 + ( 0.5 * p ) );
	if ( v < 120.0 ) {
		t += ( ( t * t * t ) + t ) / v / 4.0;
	}
	q = 0.8843 - ( 0.2368 * t );
	if ( v < 120.0 ) {
		q -= ( 1.214 / v ) + ( ( 1.208 * t ) / v );
	}
	return t * ( ( q * log( r - 1.0 ) ) + 1.4142 );
}

/**
* Evaluates the quantile function for a studentized range distribution with `r` samples and `v` degrees of freedom.
*
* ## Notes
*
* -   This implementation hardcodes `nranges` to `1`.
*
* ## References
*
* -   Ferreira, D. F., Demetrico, C. G. B., Manly, B. F. J., and Machado, A. de A. 2007. "Quantis da distribuição do máximo da amplitude estudentizada." _Rev. Mat. Est._, São Paulo, 25 (1): 117-135. <http://jaguar.fcav.unesp.br/RME/fasciculos/v25/v25_n1/A8_Daniel.pdf>.
*
* @param p    input probability
* @param r    sample size for range (must be >= 2)
* @param v    degrees of freedom (must be >= 2)
* @return     evaluated quantile function
*
* @example
* double y = stdlib_base_dists_studentized_range_quantile( 0.5, 3.0, 2.0 );
* // returns ~1.908
*/
double stdlib_base_dists_studentized_range_quantile( const double p, const double r, const double v ) {
	double aux;
	double e1;
	double e2;
	double q1;
	double q2;
	double p1;
	double p2;
	int j;

	if ( stdlib_base_is_nan( r ) || stdlib_base_is_nan( v ) || r < 2.0 || v < 2.0 ) {
		return 0.0 / 0.0;
	}
	if ( stdlib_base_is_nan( p ) || p < 0.0 || p > 1.0 ) {
		return 0.0 / 0.0;
	}
	if ( p == 0.0 ) {
		return 0.0;
	}
	if ( p == 1.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	q1 = qtrngo( p, v, r );
	for ( ;; ) {
		p1 = stdlib_base_dists_studentized_range_cdf( q1, r, v, 1.0 );
		if ( p1 > p ) {
			q1 -= 0.4;
		}
		if ( q1 < 0.0 ) {
			q1 = 0.1;
		}
		if ( p1 < p ) {
			break;
		}
	}
	aux = q1;
	if ( fabs( p1 - p ) < PCUT ) {
		return 0.0 / 0.0;
	}
	q2 = q1 + 0.5;
	for ( ;; ) {
		p2 = stdlib_base_dists_studentized_range_cdf( q2, r, v, 1.0 );
		if ( p2 < p ) {
			q2 += 0.4;
		}
		if ( q2 < 0.0 ) {
			q2 = 1.0;
		}
		if ( p2 > p ) {
			break;
		}
	}
	if ( q2 < q1 ) {
		q2 = q1 + 0.01;
	}
	j = 2;
	while ( j <= JMAX ) {
		p2 = stdlib_base_dists_studentized_range_cdf( q2, r, v, 1.0 );
		e1 = p1 - p;
		e2 = p2 - p;
		if ( e2 - e1 != 0.0 ) {
			aux = ( ( e2 * q1 ) - ( e1 * q2 ) ) / ( e2 - e1 );
		}
		if ( fabs( e1 ) < fabs( e2 ) ) {
			if ( fabs( p1 - p ) < ( PCUT * 5.0 ) ) {
				j = JMAX + 2;
			}
			q1 = aux;
			p1 = stdlib_base_dists_studentized_range_cdf( q1, r, v, 1.0 );
		} else {
			q1 = q2;
			p1 = p2;
			q2 = aux;
		}
		j += 1;
	}
	return aux;
}
